<script lang="ts">
  import { href, type Lang, type SiteId } from '#lib/site.ts';
  import { headTrainerCopy, headTrainerGallery } from '#lib/head-trainer.ts';
  import { reveal, swipe } from '#lib/effects.ts';
  import Photo from './Photo.svelte';
  import Icon from './Icon.svelte';
  let { site, lang, prefix }: { site: SiteId; lang: Lang; prefix: string } = $props();
  const c = $derived(headTrainerCopy[lang]);
  const home = $derived(href('home', lang, prefix));
  let photo = $state(0), lightbox: HTMLDialogElement;
  function openPhoto(index: number) { photo = index; lightbox.showModal(); }
  function changePhoto(step: number) { photo = (photo + step + headTrainerGallery.length) % headTrainerGallery.length; }
</script>

<article class="trainer-profile" data-profile={site}>
  <section id="top" class="profile-hero">
    <a class="profile-back" href={`${home}#trainers`}><span aria-hidden="true">←</span>{c.back}</a>
    <div class="profile-hero-grid">
      <div class="profile-hero-copy">
        <span class="eyebrow profile-kicker"><i></i>SELF CONTROL / COACHING PROFILE</span>
        <h1>{#each c.title as line}<span>{line}</span>{/each}</h1>
        <div class="profile-role"><span>{c.demo}</span><p>{c.name}</p></div>
        <p class="profile-intro">{c.intro}</p>
        <a class="underlined-link profile-story" href="#biography">{c.bioLink}<Icon name="diagonal"/></a>
      </div>
      <div class="profile-poster">
        <Photo name="trainer-head" alt={c.portrait} eager position="50% 29%"/>
        <div class="poster-top"><span>SC / 01</span><img src="/brand/mark.svg" width="50" height="37" alt=""/></div>
        <div class="poster-bottom"><span>{c.demo} / STOCK PHOTO</span><strong lang="en">SELF CONTROL<br/>HEAD COACH</strong></div>
      </div>
    </div>
    <nav class="profile-index" aria-label={lang === 'tr' ? 'Profil bölümleri' : 'Profile sections'}><a href="#biography"><span>01</span>{c.bioLink}<Icon name="diagonal" size={15}/></a><a href="#coaching"><span>02</span>{c.approachLink}<Icon name="diagonal" size={15}/></a><a href="#journal"><span>03</span>{c.galleryLink}<Icon name="diagonal" size={15}/></a></nav>
  </section>

  <section id="biography" class="section profile-biography" use:reveal>
    <div class="section-top"><span class="eyebrow">{c.bioLabel}</span><span class="eyebrow">SELF CONTROL / THE PERSON BEHIND THE PRACTICE</span></div>
    <div class="profile-bio-grid"><div class="profile-bio-heading"><h2 class="display">{c.bioTitle}</h2><div class="profile-facts"><div><span>{c.roleLabel}</span><p>{c.roleValue}</p></div><div><span>{c.focusLabel}</span><p lang="en">Muay Thai · Kick Box · MMA</p></div></div></div><div class="profile-bio-copy"><p class="profile-bio-lead">{c.bioLead}</p>{#each c.bio as paragraph}<p>{paragraph}</p>{/each}<p class="profile-demo-note">{c.bioNote}</p></div></div>
    <blockquote><span aria-hidden="true">“</span><p>{c.quote}</p><cite>{c.quoteLabel}</cite></blockquote>
  </section>

  <section id="coaching" class="section profile-coaching" use:reveal>
    <div class="section-top"><span class="eyebrow">{c.approachLabel}</span><span class="eyebrow">LISTEN. BUILD. REPEAT.</span></div>
    <div class="profile-approach-heading"><h2 class="display">{c.approachTitle}</h2><span class="profile-symbol" aria-hidden="true">↗</span></div>
    <div class="profile-principles">{#each c.principles as principle, index}<div><span class="eyebrow">0{index + 1} / SELF CONTROL</span><h3>{principle.title}</h3><p>{principle.body}</p></div>{/each}</div>
  </section>

  <section id="journal" class="section profile-journal" use:reveal>
    <div class="section-top"><span class="eyebrow">{c.galleryLabel}</span><span class="eyebrow">06 / FRAMES OF PRACTICE</span></div>
    <div class="section-heading"><h2 class="display">{c.galleryTitle}</h2><p>{c.galleryBody}</p></div>
    <div class="profile-bento" aria-label={c.gallery}>{#each headTrainerGallery as frame, index}<button class="bento-tile tile-{index}" onclick={() => openPhoto(index)} aria-label={`${c.open}: ${c.photoLabels[index]}`}><Photo name={frame.image} alt={c.photoAlts[index]} position={frame.position}/><span class="bento-top">0{index + 1} / SC</span><span class="bento-bottom"><span>{c.photoLabels[index]}</span><span class="bento-plus"><Icon name="plus" size={18}/></span></span></button>{/each}</div>
    <p class="photo-note">{c.galleryNote}</p>
  </section>

  <section class="section profile-contact" use:reveal><span class="eyebrow">{c.ctaLabel}</span><div><h2 class="display">{c.ctaTitle}</h2><div><p>{c.ctaBody}</p><a class="button solid" href={`${home}#start`}>{c.cta}<Icon name="diagonal"/></a><a class="quiet-link" href={`${home}#team`}>{c.return}<Icon name="diagonal" size={16}/></a></div></div><span class="profile-contact-signature">{c.signature}</span></section>
</article>

<dialog class="gallery-dialog profile-lightbox" bind:this={lightbox} use:swipe={changePhoto} aria-label={c.gallery} onclick={(event) => { if (event.target === lightbox) lightbox.close(); }} onkeydown={(event) => { if (event.key === 'ArrowRight') changePhoto(1); if (event.key === 'ArrowLeft') changePhoto(-1); }}><div class="gallery-dialog-top"><span class="eyebrow">SELF CONTROL / {c.demo}</span><button class="dialog-close" aria-label={c.close} onclick={() => lightbox.close()}><Icon name="close"/></button></div><Photo name={headTrainerGallery[photo].image} alt={c.photoAlts[photo]} eager position={headTrainerGallery[photo].position}/><div class="gallery-dialog-bottom"><button aria-label={c.previous} onclick={() => changePhoto(-1)}>←</button><span>0{photo + 1} / 06 — {c.photoLabels[photo]}</span><button aria-label={c.next} onclick={() => changePhoto(1)}>→</button></div><p class="photo-note">{c.galleryNote}</p></dialog>

